  const pattern = `%${q.replace(/%/g, '\\%').replace(/_/g, '\\_')}%`;
  const rows = await this.leadsRepo
    .createQueryBuilder('l')
    .where('l.tenantId = :tenantId', { tenantId })
    .andWhere(
      '(l.name ILIKE :pat ESCAPE \'\\\' OR l.email ILIKE :pat ESCAPE \'\\\' OR l.phone ILIKE :pat ESCAPE \'\\\')',
      { pat: pattern },
    )
    .orderBy('l.updatedAt', 'DESC')
    .take(limit)
    .getMany();
  return {
    ok: true,
    leads: rows.map((l) => ({
      id: l.id,
      name: l.name,
      status: l.status,
      source: l.source,
      email: l.email,
      phone: l.phone,
      createdAt: l.createdAt,
    })),
  };
}

