import * as crypto from 'crypto';

export type EmailOAuthStatePayload = {
  tenantId: string;
  userId: string;
  redirect: string;
  provider: 'gmail' | 'outlook';
};

function oauthSecret(): string {
  return process.env.JWT_SECRET || 'changeme';
}

export function encodeEmailOAuthState(payload: EmailOAuthStatePayload): string {
  const body = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url');
  const sig = crypto
    .createHmac('sha256', oauthSecret())
    .update(body)
    .digest('base64url');
  return `${body}.${sig}`;
}

export function decodeEmailOAuthState(
  state: string,
): EmailOAuthStatePayload | null {
  try {
    const dot = state.indexOf('.');
    if (dot <= 0) return null;
    const body = state.slice(0, dot);
    const sig = state.slice(dot + 1);
    const expected = crypto
      .createHmac('sha256', oauthSecret())
      .update(body)
      .digest('base64url');
    const a = Buffer.from(sig);
    const b = Buffer.from(expected);
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
    const data = JSON.parse(Buffer.from(body, 'base64url').toString('utf8'));
    if (!data?.tenantId || !data?.userId) return null;
    if (data.provider !== 'gmail' && data.provider !== 'outlook') return null;
    if (typeof data.redirect !== 'string') return null;
    return {
      tenantId: String(data.tenantId),
      userId: String(data.userId),
      redirect: String(data.redirect),
      provider: data.provider,
    };
  } catch {
    return null;
  }
}

import {
  BadRequestException,
  Injectable,
  Logger,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import axios from 'axios';
import { EmailAccount } from './email-account.entity';
import {
  decodeEmailOAuthState,
  encodeEmailOAuthState,
  type EmailOAuthStatePayload,
} from './email-oauth-state.util';
import { PlatformSettingsService } from '../platform-settings/platform-settings.service';

const GMAIL_SCOPES = [
  'https://www.googleapis.com/auth/gmail.modify',
  'https://www.googleapis.com/auth/gmail.send',
  'https://www.googleapis.com/auth/userinfo.email',
  'openid',
].join(' ');

const OUTLOOK_SCOPES = [
  'offline_access',
  'openid',
  'email',
  'https://graph.microsoft.com/Mail.ReadWrite',
  'https://graph.microsoft.com/Mail.Send',
  'https://graph.microsoft.com/User.Read',
].join(' ');

@Injectable()
export class EmailOAuthService {
  private readonly log = new Logger(EmailOAuthService.name);

  constructor(
    @InjectRepository(EmailAccount)
    private readonly accountRepo: Repository<EmailAccount>,
    private readonly platformSettings: PlatformSettingsService,
  ) {}

  apiPublicBase(): string {
    const base = (process.env.PUBLIC_API_URL || '').replace(/\/$/, '');
    if (!base) {
      throw new BadRequestException(
        'PUBLIC_API_URL is not configured (needed for OAuth redirect_uri)',
      );
    }
    return base;
  }

  googleRedirectUri(): string {
    return `${this.apiPublicBase()}/v1/email/oauth/google/callback`;
  }

  outlookRedirectUri(): string {
    return `${this.apiPublicBase()}/v1/email/oauth/microsoft/callback`;
  }

  async buildGoogleAuthUrl(payload: EmailOAuthStatePayload): Promise<string> {
    const { clientId } = await this.platformSettings.getGoogleOAuthConfig();
    if (!clientId?.trim()) {
      throw new BadRequestException(
        'Google OAuth client id is not configured (platform settings or GOOGLE_OAUTH_CLIENT_ID)',
      );
    }
    const state = encodeEmailOAuthState(payload);
    const params = new URLSearchParams({
      client_id: clientId.trim(),
      redirect_uri: this.googleRedirectUri(),
      response_type: 'code',
      scope: GMAIL_SCOPES,
      access_type: 'offline',
      prompt: 'consent',
      state,
    });
    return `https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`;
  }

  async buildMicrosoftAuthUrl(payload: EmailOAuthStatePayload): Promise<string> {
    const clientId = (
      process.env.MICROSOFT_OAUTH_CLIENT_ID ||
      process.env.OUTLOOK_OAUTH_CLIENT_ID ||
      ''
    ).trim();
    if (!clientId) {
      throw new BadRequestException(
        'Microsoft OAuth is not configured (MICROSOFT_OAUTH_CLIENT_ID)',
      );
    }
    const state = encodeEmailOAuthState(payload);
    const params = new URLSearchParams({
      client_id: clientId,
      response_type: 'code',
      redirect_uri: this.outlookRedirectUri(),
      response_mode: 'query',
      scope: OUTLOOK_SCOPES,
      state,
    });
    return `https://login.microsoftonline.com/common/oauth2/v2.0/authorize?${params.toString()}`;
  }

  async handleGoogleCallback(code: string, state: string): Promise<void> {
    const decoded = decodeEmailOAuthState(state);
    if (!decoded || decoded.provider !== 'gmail') {
      throw new BadRequestException('Invalid OAuth state');
    }
    const { clientId, clientSecret } =
      await this.platformSettings.getGoogleOAuthConfig();
    if (!clientId?.trim() || !clientSecret?.trim()) {
      throw new BadRequestException('Google OAuth client credentials missing');
    }
    const tokenRes = await axios.post<{
      access_token: string;
      refresh_token?: string;
      expires_in: number;
    }>(
      'https://oauth2.googleapis.com/token',
      new URLSearchParams({
        code,
        client_id: clientId.trim(),
        client_secret: clientSecret.trim(),
        redirect_uri: this.googleRedirectUri(),
        grant_type: 'authorization_code',
      }).toString(),
      { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } },
    );
    const access = tokenRes.data.access_token;
    const refresh = tokenRes.data.refresh_token;
    if (!access) {
      throw new BadRequestException('No access_token from Google');
    }
    const userRes = await axios.get<{ email?: string }>(
      'https://www.googleapis.com/oauth2/v2/userinfo',
      { headers: { Authorization: `Bearer ${access}` } },
    );
    const email = (userRes.data.email || '').trim().toLowerCase();
    if (!email) {
      throw new BadRequestException('Could not read Google account email');
    }
    const expiresAt = new Date(
      Date.now() + (tokenRes.data.expires_in || 3600) * 1000,
    );
    await this.upsertOAuthAccount({
      tenantId: decoded.tenantId,
      email,
      provider: 'gmail',
      accessToken: access,
      refreshToken: refresh || null,
      expiresAt,
      userId: decoded.userId,
    });
  }

  async handleMicrosoftCallback(code: string, state: string): Promise<void> {
    const decoded = decodeEmailOAuthState(state);
    if (!decoded || decoded.provider !== 'outlook') {
      throw new BadRequestException('Invalid OAuth state');
    }
    const clientId = (
      process.env.MICROSOFT_OAUTH_CLIENT_ID ||
      process.env.OUTLOOK_OAUTH_CLIENT_ID ||
      ''
    ).trim();
    const clientSecret = (
      process.env.MICROSOFT_OAUTH_CLIENT_SECRET ||
      process.env.OUTLOOK_OAUTH_CLIENT_SECRET ||
      ''
    ).trim();
    if (!clientId || !clientSecret) {
      throw new BadRequestException('Microsoft OAuth credentials missing');
    }
    const tokenRes = await axios.post<{
      access_token: string;
      refresh_token?: string;
      expires_in: number;
    }>(
      'https://login.microsoftonline.com/common/oauth2/v2.0/token',
      new URLSearchParams({
        client_id: clientId,
        client_secret: clientSecret,
        code,
        redirect_uri: this.outlookRedirectUri(),
        grant_type: 'authorization_code',
      }).toString(),
      { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } },
    );
    const access = tokenRes.data.access_token;
    const refresh = tokenRes.data.refresh_token;
    if (!access) {
      throw new BadRequestException('No access_token from Microsoft');
    }
    const me = await axios.get<{ mail?: string; userPrincipalName?: string }>(
      'https://graph.microsoft.com/v1.0/me',
      { headers: { Authorization: `Bearer ${access}` } },
    );
    const email = (
      me.data.mail ||
      me.data.userPrincipalName ||
      ''
    )
      .trim()
      .toLowerCase();
    if (!email) {
      throw new BadRequestException('Could not read Microsoft account email');
    }
    const expiresAt = new Date(
      Date.now() + (tokenRes.data.expires_in || 3600) * 1000,
    );
    await this.upsertOAuthAccount({
      tenantId: decoded.tenantId,
      email,
      provider: 'outlook',
      accessToken: access,
      refreshToken: refresh || null,
      expiresAt,
      userId: decoded.userId,
    });
  }

  private async upsertOAuthAccount(params: {
    tenantId: string;
    email: string;
    provider: 'gmail' | 'outlook';
    accessToken: string;
    refreshToken: string | null;
    expiresAt: Date;
    userId: string;
  }): Promise<EmailAccount> {
    const existing = await this.accountRepo.findOne({
      where: { tenantId: params.tenantId, email: params.email },
    });
    const metaBase =
      existing?.meta && typeof existing.meta === 'object' && !Array.isArray(existing.meta)
        ? { ...(existing.meta as Record<string, unknown>) }
        : {};
    metaBase.connectedViaOAuth = true;
    metaBase.connectedByUserId = params.userId;
    metaBase.leadIngestion = {
      autoCreateFromUnknown:
        (metaBase.leadIngestion as any)?.autoCreateFromUnknown !== false,
      skipDomains: Array.isArray((metaBase.leadIngestion as any)?.skipDomains)
        ? (metaBase.leadIngestion as any).skipDomains
        : [],
    };
    if (existing) {
      existing.oauthProvider = params.provider;
      existing.oauthAccessToken = params.accessToken;
      if (params.refreshToken) {
        existing.oauthRefreshToken = params.refreshToken;
      }
      existing.oauthExpiresAt = params.expiresAt;
      existing.status = 'active';
      existing.lastError = null;
      existing.syncIncoming = true;
      existing.syncOutgoing = true;
      existing.imapHost = null;
      existing.imapPort = null;
      existing.imapUsername = null;
      existing.imapPassword = null;
      existing.smtpHost = null;
      existing.smtpPort = null;
      existing.smtpUsername = null;
      existing.smtpPassword = null;
      existing.meta = metaBase;
      return this.accountRepo.save(existing);
    }
    const acc = this.accountRepo.create({
      tenantId: params.tenantId,
      email: params.email,
      name: params.email,
      oauthProvider: params.provider,
      oauthAccessToken: params.accessToken,
      oauthRefreshToken: params.refreshToken,
      oauthExpiresAt: params.expiresAt,
      status: 'active',
      syncIncoming: true,
      syncOutgoing: true,
      syncFolder: 'INBOX',
      meta: metaBase,
    });
    return this.accountRepo.save(acc);
  }

  /**
   * Обновляет access_token у аккаунта при необходимости. Возвращает актуальный токен.
   */
  async ensureAccessToken(account: EmailAccount): Promise<string> {
    if (!account.oauthRefreshToken) {
      throw new BadRequestException('Account has no refresh token');
    }
    const skewMs = 120_000;
    if (
      account.oauthAccessToken &&
      account.oauthExpiresAt &&
      account.oauthExpiresAt.getTime() > Date.now() + skewMs
    ) {
      return account.oauthAccessToken;
    }
    if (account.oauthProvider === 'gmail') {
      return this.refreshGoogle(account);
    }
    if (account.oauthProvider === 'outlook') {
      return this.refreshMicrosoft(account);
    }
    throw new BadRequestException('Unknown oauth provider');
  }

  private async refreshGoogle(account: EmailAccount): Promise<string> {
    const { clientId, clientSecret } =
      await this.platformSettings.getGoogleOAuthConfig();
    if (!clientId?.trim() || !clientSecret?.trim()) {
      throw new BadRequestException('Google OAuth credentials missing');
    }
    try {
      const res = await axios.post<{
        access_token: string;
        expires_in: number;
      }>(
        'https://oauth2.googleapis.com/token',
        new URLSearchParams({
          client_id: clientId.trim(),
          client_secret: clientSecret.trim(),
          refresh_token: account.oauthRefreshToken!,
          grant_type: 'refresh_token',
        }).toString(),
        { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } },
      );
      const access = res.data.access_token;
      if (!access) throw new Error('no access_token');
      account.oauthAccessToken = access;
      account.oauthExpiresAt = new Date(
        Date.now() + (res.data.expires_in || 3600) * 1000,
      );
      account.status = 'active';
      account.lastError = null;
      await this.accountRepo.save(account);
      return access;
    } catch (e: any) {
      this.log.warn(`Google token refresh failed: ${e?.message || e}`);
      account.status = 'error';
      account.lastError = e?.response?.data?.error_description || e?.message || 'refresh_failed';
      await this.accountRepo.save(account);
      throw e;
    }
  }

  private async refreshMicrosoft(account: EmailAccount): Promise<string> {
    const clientId = (
      process.env.MICROSOFT_OAUTH_CLIENT_ID ||
      process.env.OUTLOOK_OAUTH_CLIENT_ID ||
      ''
    ).trim();
    const clientSecret = (
      process.env.MICROSOFT_OAUTH_CLIENT_SECRET ||
      process.env.OUTLOOK_OAUTH_CLIENT_SECRET ||
      ''
    ).trim();
    if (!clientId || !clientSecret) {
      throw new BadRequestException('Microsoft OAuth credentials missing');
    }
    try {
      const res = await axios.post<{
        access_token: string;
        expires_in: number;
      }>(
        'https://login.microsoftonline.com/common/oauth2/v2.0/token',
        new URLSearchParams({
          client_id: clientId,
          client_secret: clientSecret,
          refresh_token: account.oauthRefreshToken!,
          grant_type: 'refresh_token',
        }).toString(),
        { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } },
      );
      const access = res.data.access_token;
      if (!access) throw new Error('no access_token');
      account.oauthAccessToken = access;
      account.oauthExpiresAt = new Date(
        Date.now() + (res.data.expires_in || 3600) * 1000,
      );
      account.status = 'active';
      account.lastError = null;
      await this.accountRepo.save(account);
      return access;
    } catch (e: any) {
      this.log.warn(`Microsoft token refresh failed: ${e?.message || e}`);
      account.status = 'error';
      account.lastError = e?.response?.data?.error_description || e?.message || 'refresh_failed';
      await this.accountRepo.save(account);
      throw e;
    }
  }
}

import { Injectable, Logger, forwardRef, Inject } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, Not, IsNull } from 'typeorm';
import { Cron, CronExpression } from '@nestjs/schedule';
import axios from 'axios';
import { EmailAccount } from './email-account.entity';
import { EmailMessage } from './email-message.entity';
import { EmailOAuthService } from './email-oauth.service';
import { LeadsService } from '../leads/leads.service';
import { AutomationsService } from '../automations/automations.service';
import { TriggerEvent } from '../automations/automation.entity';

function parseEmailAddress(raw: string): { email: string; name: string | null } {
  const s = (raw || '').trim();
  const m = s.match(/^(?:"([^"]*)"|([^<]+?))\s*<([^>]+)>$/);
  if (m) {
    const name = (m[1] || m[2] || '').trim() || null;
    return { email: m[3].trim().toLowerCase(), name };
  }
  return { email: s.replace(/^<|>$/g, '').trim().toLowerCase(), name: null };
}

function parseAddressList(raw: string | undefined): string[] {
  if (!raw) return [];
  const out: string[] = [];
  for (const part of raw.split(',')) {
    const { email } = parseEmailAddress(part);
    if (email) out.push(email);
  }
  return out;
}

function decodeBase64Url(data: string | undefined): string {
  if (!data) return '';
  const pad = data.length % 4 === 0 ? '' : '='.repeat(4 - (data.length % 4));
  const b64 = data.replace(/-/g, '+').replace(/_/g, '/') + pad;
  try {
    return Buffer.from(b64, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function walkGmailParts(
  part: any,
  acc: { text?: string; html?: string; attachments: Array<{ filename: string; contentType: string; size: number }> },
): void {
  if (!part) return;
  const mime = part.mimeType || '';
  if (mime === 'text/plain' && part.body?.data && !acc.text) {
    acc.text = decodeBase64Url(part.body.data);
  }
  if (mime === 'text/html' && part.body?.data && !acc.html) {
    acc.html = decodeBase64Url(part.body.data);
  }
  if (part.filename && part.body?.attachmentId) {
    acc.attachments.push({
      filename: part.filename,
      contentType: mime || 'application/octet-stream',
      size: Number(part.body.size || 0),
    });
  }
  if (Array.isArray(part.parts)) {
    for (const p of part.parts) walkGmailParts(p, acc);
  }
}

@Injectable()
export class EmailSyncService {
  private readonly log = new Logger(EmailSyncService.name);
  private runLock = false;

  constructor(
    @InjectRepository(EmailAccount)
    private readonly accountRepo: Repository<EmailAccount>,
    @InjectRepository(EmailMessage)
    private readonly messageRepo: Repository<EmailMessage>,
    private readonly emailOAuth: EmailOAuthService,
    @Inject(forwardRef(() => LeadsService))
    private readonly leadsService: LeadsService,
    @Inject(forwardRef(() => AutomationsService))
    private readonly automationsService: AutomationsService,
  ) {}

  @Cron(CronExpression.EVERY_2_MINUTES)
  async cronSyncAllTenants(): Promise<void> {
    if (this.runLock) return;
    this.runLock = true;
    try {
      const accounts = await this.accountRepo.find({
        where: {
          status: 'active',
          syncIncoming: true,
          oauthRefreshToken: Not(IsNull()),
        },
      });
      for (const a of accounts) {
        try {
          await this.syncAccount(a.id);
        } catch (e: any) {
          this.log.warn(`sync ${a.id}: ${e?.message || e}`);
        }
      }
    } finally {
      this.runLock = false;
    }
  }

  async syncAccount(accountId: string): Promise<{ imported: number }> {
    const account = await this.accountRepo.findOne({ where: { id: accountId } });
    if (!account || !account.oauthRefreshToken || !account.syncIncoming) {
      return { imported: 0 };
    }
    await this.emailOAuth.ensureAccessToken(account);
    const reloaded = await this.accountRepo.findOne({ where: { id: accountId } });
    if (!reloaded) return { imported: 0 };
    if (reloaded.oauthProvider === 'gmail') {
      return this.syncGmailInbox(reloaded);
    }
    if (reloaded.oauthProvider === 'outlook') {
      return this.syncOutlookInbox(reloaded);
    }
    return { imported: 0 };
  }

  private getIngestionConfig(account: EmailAccount): {
    autoCreateFromUnknown: boolean;
    skipDomains: string[];
  } {
    const m = account.meta as Record<string, any> | null;
    const ing = m?.leadIngestion;
    return {
      autoCreateFromUnknown: ing?.autoCreateFromUnknown !== false,
      skipDomains: Array.isArray(ing?.skipDomains)
        ? ing.skipDomains.map((x: string) => String(x).toLowerCase())
        : [],
    };
  }

  private shouldSkipDomain(email: string, skipDomains: string[]): boolean {
    const dom = email.split('@')[1]?.toLowerCase() || '';
    return skipDomains.some((d) => dom === d || dom.endsWith(`.${d}`));
  }

  private async resolveLeadForIncoming(
    tenantId: string,
    account: EmailAccount,
    fromAddr: string,
    fromName: string | null,
  ): Promise<string | null> {
    const selfEmail = account.email.trim().toLowerCase();
    if (fromAddr === selfEmail) return null;
    const { autoCreateFromUnknown, skipDomains } = this.getIngestionConfig(account);
    if (this.shouldSkipDomain(fromAddr, skipDomains)) {
      return null;
    }
    const lead = await this.leadRepoFindByEmail(tenantId, fromAddr);
    if (lead) return lead.id;
    if (!autoCreateFromUnknown) return null;
    const created = await this.leadsService.createForTenant(tenantId, {
      name: fromName || fromAddr.split('@')[0] || fromAddr,
      email: fromAddr,
      source: 'email',
      meta: {
        createdFromMailbox: true,
        emailAccountId: account.id,
      },
    });
    return created.id;
  }

  private async leadRepoFindByEmail(
    tenantId: string,
    email: string,
  ): Promise<{ id: string } | null> {
    const norm = email.trim().toLowerCase();
    const row = await this.leadsService['leadsRepo']?.findOne?.({
      where: { tenantId, email: norm },
    });
    if (row) return { id: row.id };
    return null;
  }

  // LeadsService doesn't expose leadsRepo - use query via createForTenant only or inject Lead repo in EmailSyncService

  private async findLeadIdByEmail(
    tenantId: string,
    email: string,
  ): Promise<string | null> {
    const norm = email.trim().toLowerCase();
    const qb = this.leadsService as any;
    const repo = qb.leadsRepo as Repository<any>;
    if (!repo) return null;
    const row = await repo
      .createQueryBuilder('l')
      .where('l.tenantId = :tid', { tid: tenantId })
      .andWhere('LOWER(TRIM(l.email)) = :em', { em: norm })
      .getOne();
    return row?.id || null;
  }

  private async resolveLeadForIncomingFixed(
    tenantId: string,
    account: EmailAccount,
    fromAddr: string,
    fromName: string | null,
  ): Promise<string | null> {
    const selfEmail = account.email.trim().toLowerCase();
    if (fromAddr === selfEmail) return null;
    const { autoCreateFromUnknown, skipDomains } = this.getIngestionConfig(account);
    if (this.shouldSkipDomain(fromAddr, skipDomains)) return null;
    const existing = await this.findLeadIdByEmail(tenantId, fromAddr);
    if (existing) return existing;
    if (!autoCreateFromUnknown) return null;
    const created = await this.leadsService.createForTenant(tenantId, {
      name: fromName || fromAddr.split('@')[0] || fromAddr,
      email: fromAddr,
      source: 'email',
      meta: {
        createdFromMailbox: true,
        emailAccountId: account.id,
      },
    });
    return created.id;
  }

  private async syncGmailInbox(
    account: EmailAccount,
  ): Promise<{ imported: number }> {
    const token = await this.emailOAuth.ensureAccessToken(account);
    const listRes = await axios.get<{
      messages?: Array<{ id: string }>;
    }>('https://gmail.googleapis.com/gmail/v1/users/me/messages', {
      params: { maxResults: 40 },
      headers: { Authorization: `Bearer ${token}` },
    });
    const ids = listRes.data.messages?.map((m) => m.id) || [];
    let imported = 0;
    for (const gid of ids) {
      const mid = `gmail:${account.id}:${gid}`;
      const exists = await this.messageRepo.findOne({
        where: { tenantId: account.tenantId, messageId: mid },
      });
      if (exists) continue;
      const full = await axios.get<any>(
        `https://gmail.googleapis.com/gmail/v1/users/me/messages/${gid}`,
        {
          params: { format: 'full' },
          headers: { Authorization: `Bearer ${token}` },
        },
      );
      const headers = full.data.payload?.headers || [];
      const getH = (n: string) =>
        headers.find(
          (h: any) => String(h.name || '').toLowerCase() === n.toLowerCase(),
        )?.value || '';
      const fromRaw = getH('From');
      const { email: fromAddr, name: fromName } = parseEmailAddress(fromRaw);
      const toRaw = getH('To');
      const ccRaw = getH('Cc');
      const subject = getH('Subject') || null;
      const dateHdr = getH('Date');
      const date = dateHdr ? new Date(dateHdr) : new Date();
      const acc = {
        text: undefined as string | undefined,
        html: undefined as string | undefined,
        attachments: [] as Array<{
          filename: string;
          contentType: string;
          size: number;
        }>,
      };
      walkGmailParts(full.data.payload, acc);
      const selfEmail = account.email.trim().toLowerCase();
      const direction =
        fromAddr === selfEmail ? 'outgoing' : 'incoming';
      let leadId: string | null = null;
      if (direction === 'incoming') {
        leadId = await this.resolveLeadForIncomingFixed(
          account.tenantId,
          account,
          fromAddr,
          fromName,
        );
      }
      const msg = this.messageRepo.create({
        tenantId: account.tenantId,
        accountId: account.id,
        messageId: mid,
        threadId: full.data.threadId || null,
        direction,
        from: fromAddr || fromRaw,
        fromName,
        to: parseAddressList(toRaw),
        cc: parseAddressList(ccRaw),
        bcc: [],
        subject,
        textBody: acc.text || null,
        htmlBody: acc.html || null,
        attachments: acc.attachments.length ? acc.attachments : null,
        contactId: null,
        companyId: null,
        leadId,
        saleId: null,
        date: Number.isNaN(date.getTime()) ? new Date() : date,
        isRead: full.data.labelIds?.includes('UNREAD') === false,
        labels: full.data.labelIds || [],
        headers: Object.fromEntries(
          headers.map((h: any) => [h.name, h.value]),
        ),
        meta: {
          provider: 'gmail',
          gmailId: gid,
          hasCalendarAttachment: acc.attachments.some((a) =>
            /\.ics$/i.test(a.filename),
          ),
        },
      });
      await this.messageRepo.save(msg);
      imported += 1;
      try {
        await this.automationsService.triggerAutomation(
          account.tenantId,
          TriggerEvent.EMAIL_RECEIVED,
          {
            entityType: 'email',
            entityId: msg.id,
            email: msg,
            accountId: account.id,
            leadId,
          },
        );
      } catch {
        /* ignore */
      }
    }
    account.lastSyncAt = new Date();
    account.lastError = null;
    await this.accountRepo.save(account);
    return { imported };
  }

  private async syncOutlookInbox(
    account: EmailAccount,
  ): Promise<{ imported: number }> {
    const token = await this.emailOAuth.ensureAccessToken(account);
    const listRes = await axios.get<{ value?: any[] }>(
      'https://graph.microsoft.com/v1.0/me/mailFolders/inbox/messages',
      {
        params: { $top: 40, $orderby: 'receivedDateTime desc' },
        headers: { Authorization: `Bearer ${token}` },
      },
    );
    const items = listRes.data.value || [];
    let imported = 0;
    for (const it of items) {
      const oid = it.id;
      if (!oid) continue;
      const mid = `outlook:${account.id}:${oid}`;
      const exists = await this.messageRepo.findOne({
        where: { tenantId: account.tenantId, messageId: mid },
      });
      if (exists) continue;
      const fromAddr = (it.from?.emailAddress?.address || '').toLowerCase();
      const fromName = it.from?.emailAddress?.name || null;
      const toList: string[] = Array.isArray(it.toRecipients)
        ? it.toRecipients
            .map((r: any) => r.emailAddress?.address)
            .filter(Boolean)
        : [];
      const ccList: string[] = Array.isArray(it.ccRecipients)
        ? it.ccRecipients
            .map((r: any) => r.emailAddress?.address)
            .filter(Boolean)
        : [];
      const selfEmail = account.email.trim().toLowerCase();
      const direction =
        fromAddr === selfEmail ? 'outgoing' : 'incoming';
      let leadId: string | null = null;
      if (direction === 'incoming' && fromAddr) {
        leadId = await this.resolveLeadForIncomingFixed(
          account.tenantId,
          account,
          fromAddr,
          fromName,
        );
      }
      const att =
        Array.isArray(it.attachments) || it.hasAttachments
          ? await this.fetchOutlookAttachmentsMeta(token, oid)
          : [];
      const msg = this.messageRepo.create({
        tenantId: account.tenantId,
        accountId: account.id,
        messageId: mid,
        threadId: it.conversationId || null,
        direction,
        from: fromAddr || 'unknown',
        fromName,
        to: toList,
        cc: ccList,
        bcc: [],
        subject: it.subject || null,
        textBody: it.body?.contentType === 'text' ? it.body.content : null,
        htmlBody: it.body?.contentType === 'html' ? it.body.content : null,
        attachments: att.length ? att : null,
        contactId: null,
        companyId: null,
        leadId,
        saleId: null,
        date: it.receivedDateTime
          ? new Date(it.receivedDateTime)
          : new Date(),
        isRead: Boolean(it.isRead),
        labels: [],
        headers: null,
        meta: {
          provider: 'outlook',
          outlookId: oid,
          hasCalendarAttachment: att.some((a) => /\.ics$/i.test(a.filename)),
        },
      });
      await this.messageRepo.save(msg);
      imported += 1;
      try {
        await this.automationsService.triggerAutomation(
          account.tenantId,
          TriggerEvent.EMAIL_RECEIVED,
          {
            entityType: 'email',
            entityId: msg.id,
            email: msg,
            accountId: account.id,
            leadId,
          },
        );
      } catch {
        /* ignore */
      }
    }
    account.lastSyncAt = new Date();
    account.lastError = null;
    await this.accountRepo.save(account);
    return { imported };
  }

  private async fetchOutlookAttachmentsMeta(
    token: string,
    messageId: string,
  ): Promise<Array<{ filename: string; contentType: string; size: number }>> {
    try {
      const res = await axios.get<{ value?: any[] }>(
        `https://graph.microsoft.com/v1.0/me/messages/${messageId}/attachments`,
        { headers: { Authorization: `Bearer ${token}` } },
      );
      const out: Array<{ filename: string; contentType: string; size: number }> =
        [];
      for (const a of res.data.value || []) {
        if (a['@odata.type'] === '#microsoft.graph.fileAttachment') {
          out.push({
            filename: a.name || 'file',
            contentType: a.contentType || 'application/octet-stream',
            size: Number(a.size || 0),
          });
        }
      }
      return out;
    } catch {
      return [];
    }
  }
}

