// src/pages/email/EmailAccountsPage.tsx
import React, { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { MainLayout } from '../../layout/MainLayout';
import { useTranslation } from 'react-i18next';
import {
  fetchEmailAccounts,
  deleteEmailAccount,
  testSmtpConnection,
  startEmailOAuthGoogle,
  startEmailOAuthMicrosoft,
  syncEmailMailboxNow,
  patchEmailAccountIngestion,
  type EmailAccount,
} from '../../api/email';

export const EmailAccountsPage: React.FC = () => {
  const { t } = useTranslation();
  const [accounts, setAccounts] = useState<EmailAccount[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [oauthBusy, setOauthBusy] = useState<'gmail' | 'outlook' | null>(null);
  const [syncingId, setSyncingId] = useState<string | null>(null);
  const [ingestionOpenId, setIngestionOpenId] = useState<string | null>(null);
  const [ingestionAuto, setIngestionAuto] = useState(true);
  const [ingestionDomains, setIngestionDomains] = useState('');
  const [ingestionSaving, setIngestionSaving] = useState(false);
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();

  const loadAccounts = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchEmailAccounts();
      setAccounts(data);
    } catch (e: any) {
      setError(e.message || t('crm.email.accounts.errors.loadFailed'));
    } finally {
      setLoading(false);
    }
  }, [t]);

  useEffect(() => {
    void loadAccounts();
  }, [loadAccounts]);

  useEffect(() => {
    const oauth = searchParams.get('oauth');
    if (oauth === 'connected') {
      const provider = searchParams.get('provider');
      const label =
        provider === 'gmail'
          ? t('crm.email.accounts.oauthProviderGmail')
          : provider === 'outlook'
            ? t('crm.email.accounts.oauthProviderOutlook')
            : '';
      alert(
        label
          ? `${t('crm.email.accounts.oauthConnected')} (${label})`
          : t('crm.email.accounts.oauthConnected'),
      );
      searchParams.delete('oauth');
      searchParams.delete('provider');
      setSearchParams(searchParams, { replace: true });
      void loadAccounts();
    } else if (oauth === 'error') {
      alert(t('crm.email.accounts.oauthError'));
      searchParams.delete('oauth');
      setSearchParams(searchParams, { replace: true });
    }
  }, [searchParams, setSearchParams, t, loadAccounts]);

  const openIngestion = (account: EmailAccount) => {
    const li = account.meta?.leadIngestion;
    setIngestionOpenId(account.id);
    setIngestionAuto(li?.autoCreateFromUnknown !== false);
    setIngestionDomains(Array.isArray(li?.skipDomains) ? li!.skipDomains!.join(', ') : '');
  };

  const saveIngestion = async (accountId: string) => {
    setIngestionSaving(true);
    try {
      const skipDomains = ingestionDomains
        .split(',')
        .map((s) => s.trim().toLowerCase())
        .filter(Boolean);
      await patchEmailAccountIngestion(accountId, {
        autoCreateFromUnknown: ingestionAuto,
        skipDomains,
      });
      alert(t('crm.email.accounts.ingestionSaved'));
      await loadAccounts();
    } catch (e: any) {
      alert(e?.message || t('crm.email.accounts.ingestionSaveError'));
    } finally {
      setIngestionSaving(false);
    }
  };

  const handleCreate = () => navigate('/email/accounts/new');
  const handleEdit = (id: string) => navigate(`/email/accounts/${id}`);
  const handleDelete = async (id: string) => {
    if (!confirm(t('crm.email.accounts.deleteConfirm'))) return;
    try {
      await deleteEmailAccount(id);
      setAccounts((prev) => prev.filter((a) => a.id !== id));
    } catch (err: any) {
      alert(err.message || t('crm.email.accounts.errors.deleteFailed'));
    }
  };

  const handleTest = async (id: string) => {
    try {
      const result = await testSmtpConnection(id);
      if (result.success) {
        alert(t('crm.email.form.success.testSuccess'));
        void loadAccounts();
      } else {
        alert(
          `${t('crm.email.form.errors.testFailed')}: ${result.error || result.message || t('crm.email.form.errors.unknown')}`,
        );
        void loadAccounts();
      }
    } catch (err: any) {
      console.error('SMTP test error:', err);
      alert(err.message || t('crm.email.form.errors.testFailed'));
      void loadAccounts();
    }
  };

  const connectGoogle = async () => {
    setOauthBusy('gmail');
    try {
      const { url } = await startEmailOAuthGoogle();
      window.location.href = url;
    } catch (e: any) {
      alert(e?.message || t('crm.email.accounts.oauthError'));
      setOauthBusy(null);
    }
  };

  const connectMicrosoft = async () => {
    setOauthBusy('outlook');
    try {
      const { url } = await startEmailOAuthMicrosoft();
      window.location.href = url;
    } catch (e: any) {
      alert(e?.message || t('crm.email.accounts.oauthError'));
      setOauthBusy(null);
    }
  };

  const handleSync = async (id: string) => {
    setSyncingId(id);
    try {
      await syncEmailMailboxNow(id);
      await loadAccounts();
    } catch (e: any) {
      alert(e?.message || 'Sync failed');
    } finally {
      setSyncingId(null);
    }
  };

  return (
    <MainLayout>
      <div className="space-y-4">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <h1 className="text-lg font-semibold text-slate-50">{t('crm.email.accounts.title')}</h1>
            <div className="text-[11px] text-slate-500">{t('crm.email.accounts.subtitle')}</div>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <Link
              to="/email/inbox"
              className="rounded-xl border border-slate-600 px-3 py-1.5 text-xs font-medium text-slate-200 hover:bg-slate-800"
            >
              {t('crm.email.accounts.openInbox')}
            </Link>
            <button
              type="button"
              onClick={() => void connectGoogle()}
              disabled={oauthBusy !== null}
              className="rounded-xl border border-red-900/60 bg-red-950/30 px-3 py-1.5 text-xs font-medium text-red-100 hover:bg-red-950/50 disabled:opacity-50"
            >
              {oauthBusy === 'gmail' ? t('crm.email.accounts.oauthWorking') : t('crm.email.accounts.connectGmail')}
            </button>
            <button
              type="button"
              onClick={() => void connectMicrosoft()}
              disabled={oauthBusy !== null}
              className="rounded-xl border border-sky-900/60 bg-sky-950/30 px-3 py-1.5 text-xs font-medium text-sky-100 hover:bg-sky-950/50 disabled:opacity-50"
            >
              {oauthBusy === 'outlook' ? t('crm.email.accounts.oauthWorking') : t('crm.email.accounts.connectOutlook')}
            </button>
            <button
              onClick={handleCreate}
              className="rounded-xl bg-lumiva-accent px-3 py-1.5 text-xs font-semibold text-slate-950 transition-colors hover:bg-lumiva-accent-soft"
            >
              + {t('crm.email.accounts.create')}
            </button>
          </div>
        </div>

        <p className="text-[11px] text-slate-500">{t('crm.email.accounts.oauthHint')}</p>

        {error && (
          <div className="rounded-xl border border-red-800/50 bg-red-950/40 px-3 py-2 text-xs text-red-400">{error}</div>
        )}

        {loading && !error && <div className="text-xs text-slate-400">{t('crm.email.accounts.loading')}</div>}

        {!loading && !error && accounts.length === 0 && (
          <div className="rounded-3xl border border-slate-800/80 bg-slate-900/70 p-12 text-center">
            <div className="mb-2 text-sm text-slate-400">{t('crm.email.accounts.empty')}</div>
            <div className="mb-4 text-xs text-slate-500">{t('crm.email.accounts.emptyHint')}</div>
            <div className="flex flex-wrap justify-center gap-2">
              <button
                type="button"
                onClick={() => void connectGoogle()}
                className="rounded-xl border border-red-900/50 bg-red-950/20 px-4 py-2 text-xs text-red-100"
              >
                {t('crm.email.accounts.connectGmail')}
              </button>
              <button
                type="button"
                onClick={() => void connectMicrosoft()}
                className="rounded-xl border border-sky-900/50 bg-sky-950/20 px-4 py-2 text-xs text-sky-100"
              >
                {t('crm.email.accounts.connectOutlook')}
              </button>
              <button
                onClick={handleCreate}
                className="rounded-xl bg-lumiva-accent px-4 py-2 text-xs font-semibold text-slate-950 hover:bg-lumiva-accent-soft"
              >
                {t('crm.email.accounts.createFirst')}
              </button>
            </div>
          </div>
        )}

        {!loading && !error && accounts.length > 0 && (
          <div className="grid gap-3">
            {accounts.map((account) => (
              <div
                key={account.id}
                className="rounded-3xl border border-slate-800/80 bg-slate-900/70 p-4 transition-colors hover:border-slate-700 hover:bg-slate-900/80"
              >
                <div className="flex flex-wrap items-start justify-between gap-4">
                  <div className="min-w-0 flex-1">
                    <div className="mb-2 flex flex-wrap items-center gap-2">
                      <h3 className="truncate text-sm font-semibold text-slate-50">{account.email}</h3>
                      {account.name && <span className="flex-shrink-0 text-xs text-slate-400">({account.name})</span>}
                      <span
                        className={`flex-shrink-0 rounded-lg px-2 py-0.5 text-[10px] font-medium ${
                          account.status === 'active'
                            ? 'border border-emerald-800/50 bg-emerald-950/50 text-emerald-400'
                            : 'border border-red-800/50 bg-red-950/50 text-red-400'
                        }`}
                      >
                        {account.status === 'active' ? t('crm.email.accounts.statusActive') : t('crm.email.accounts.statusError')}
                      </span>
                      {account.hasOAuthTokens && account.oauthProvider === 'gmail' && (
                        <span className="rounded-lg bg-red-950/40 px-2 py-0.5 text-[10px] text-red-200">
                          {t('crm.email.accounts.oauthProviderGmail')}
                        </span>
                      )}
                      {account.hasOAuthTokens && account.oauthProvider === 'outlook' && (
                        <span className="rounded-lg bg-sky-950/40 px-2 py-0.5 text-[10px] text-sky-200">
                          {t('crm.email.accounts.oauthProviderOutlook')}
                        </span>
                      )}
                    </div>

                    <div className="flex flex-wrap items-center gap-3 text-[11px] text-slate-400">
                      {account.smtpHost && (
                        <div>
                          <span className="text-slate-500">SMTP:</span>{' '}
                          <span className="text-slate-300">
                            {account.smtpHost}:{account.smtpPort}
                          </span>
                        </div>
                      )}
                      {account.imapHost && (
                        <div>
                          <span className="text-slate-500">IMAP:</span>{' '}
                          <span className="text-slate-300">
                            {account.imapHost}:{account.imapPort}
                          </span>
                        </div>
                      )}
                      {account.lastSyncAt && (
                        <div>
                          <span className="text-slate-500">{t('crm.email.accounts.lastSync')}</span>{' '}
                          <span className="text-slate-300">{new Date(account.lastSyncAt).toLocaleString()}</span>
                        </div>
                      )}
                    </div>

                    {account.lastError && (
                      <div className="mt-2 text-[10px] text-red-400">
                        {t('crm.email.accounts.error')}: {account.lastError}
                      </div>
                    )}

                    {account.hasOAuthTokens && (
                      <div className="mt-3 border-t border-slate-800/80 pt-3">
                        <button
                          type="button"
                          onClick={() =>
                            setIngestionOpenId((id) => (id === account.id ? null : openIngestion(account) || account.id))
                          }
                          className="text-[11px] font-medium text-sky-300 hover:text-sky-200"
                        >
                          {ingestionOpenId === account.id ? '▼ ' : '▶ '}
                          {t('crm.email.accounts.ingestionTitle')}
                        </button>
                        {ingestionOpenId === account.id && (
                          <div className="mt-2 space-y-2 rounded-xl border border-slate-800 bg-slate-950/40 p-3">
                            <label className="flex cursor-pointer items-center gap-2 text-[11px] text-slate-300">
                              <input
                                type="checkbox"
                                checked={ingestionAuto}
                                onChange={(e) => setIngestionAuto(e.target.checked)}
                                className="rounded border-slate-600"
                              />
                              {t('crm.email.accounts.autoCreate')}
                            </label>
                            <div>
                              <label className="mb-1 block text-[10px] uppercase tracking-wide text-slate-500">
                                {t('crm.email.accounts.skipDomains')}
                              </label>
                              <input
                                type="text"
                                value={ingestionDomains}
                                onChange={(e) => setIngestionDomains(e.target.value)}
                                className="w-full rounded-lg border border-slate-700 bg-slate-900 px-2 py-1.5 text-xs text-slate-200"
                              />
                            </div>
                            <button
                              type="button"
                              disabled={ingestionSaving}
                              onClick={() => void saveIngestion(account.id)}
                              className="rounded-lg bg-lumiva-accent px-3 py-1 text-[11px] font-semibold text-slate-950 hover:opacity-90 disabled:opacity-50"
                            >
                              {ingestionSaving ? '…' : t('crm.email.accounts.saveIngestion')}
                            </button>
                          </div>
                        )}
                      </div>
                    )}
                  </div>

                  <div className="flex flex-shrink-0 flex-wrap items-center gap-2">
                    {account.hasOAuthTokens && (
                      <button
                        type="button"
                        disabled={syncingId === account.id}
                        onClick={() => void handleSync(account.id)}
                        className="rounded-lg border border-sky-800/60 bg-sky-950/30 px-2 py-1 text-[10px] text-sky-200 hover:bg-sky-950/50 disabled:opacity-50"
                      >
                        {syncingId === account.id ? '…' : t('crm.email.accounts.syncNow')}
                      </button>
                    )}
                    {account.smtpHost && (
                      <button
                        onClick={() => void handleTest(account.id)}
                        className="rounded-lg bg-slate-800/50 px-2 py-1 text-[10px] text-slate-300 transition-colors hover:bg-slate-700"
                        title={t('crm.email.accounts.test')}
                      >
                        {t('crm.email.accounts.test')}
                      </button>
                    )}
                    <button
                      onClick={() => handleEdit(account.id)}
                      className="rounded-lg bg-blue-600 px-2 py-1 text-[10px] text-white transition-colors hover:bg-blue-700"
                    >
                      {t('crm.email.accounts.edit')}
                    </button>
                    <button
                      onClick={() => void handleDelete(account.id)}
                      className="rounded-lg px-2 py-1 text-[10px] text-red-400 transition-colors hover:bg-red-950/30 hover:text-red-300"
                    >
                      {t('crm.email.accounts.delete')}
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </MainLayout>
  );
};

import React, { useEffect } from 'react';
import { createPortal } from 'react-dom';

export type CrmShellModalProps = {
  open: boolean;
  title: string;
  message: string;
  variant?: 'info' | 'error';
  /** Если есть — показываем вторую кнопку «Отмена» */
  cancelLabel?: string;
  confirmLabel?: string;
  onClose: () => void;
  onConfirm?: () => void;
};

/**
 * Единое модальное окно в стиле CRM (как AI / почтовый композер): белая панель, тень, оверлей.
 */
export const CrmShellModal: React.FC<CrmShellModalProps> = ({
  open,
  title,
  message,
  variant = 'info',
  cancelLabel,
  confirmLabel = 'OK',
  onClose,
  onConfirm,
}) => {
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  if (!open || typeof document === 'undefined') return null;

  const isConfirm = Boolean(cancelLabel);

  return createPortal(
    <div
      className="fixed inset-0 z-[85] flex items-end justify-center bg-slate-900/50 p-3 sm:items-center sm:p-6"
      role="dialog"
      aria-modal
      aria-labelledby="crm-shell-modal-title"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className="w-full max-w-md overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl"
        onMouseDown={(e) => e.stopPropagation()}
      >
        <div
          className={`border-b px-4 py-3 sm:px-5 ${
            variant === 'error' ? 'border-rose-100 bg-rose-50/80' : 'border-slate-100 bg-slate-50/80'
          }`}
        >
          <h2 id="crm-shell-modal-title" className="text-sm font-semibold text-slate-900">
            {title}
          </h2>
        </div>
        <div className="max-h-[min(60vh,320px)] overflow-y-auto px-4 py-4 text-sm leading-relaxed text-slate-700 sm:px-5">
          <p className="whitespace-pre-wrap">{message}</p>
        </div>
        <div className="flex justify-end gap-2 border-t border-slate-100 bg-slate-50/50 px-4 py-3 sm:px-5">
          {isConfirm ? (
            <>
              <button
                type="button"
                onClick={onClose}
                className="rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-semibold text-slate-700 shadow-sm hover:bg-slate-50"
              >
                {cancelLabel}
              </button>
              <button
                type="button"
                onClick={() => {
                  onConfirm?.();
                  onClose();
                }}
                className="rounded-xl bg-slate-900 px-4 py-2 text-xs font-semibold text-white shadow-sm hover:bg-slate-800"
              >
                {confirmLabel}
              </button>
            </>
          ) : (
            <button
              type="button"
              onClick={onClose}
              className="rounded-xl bg-slate-900 px-4 py-2 text-xs font-semibold text-white shadow-sm hover:bg-slate-800"
            >
              {confirmLabel}
            </button>
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
};

