import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { sendEmail, type EmailAccount, type EmailMessage } from '../../api/email';

const TEAL = '#45a094';

export type EmailComposeModalProps = {
  open: boolean;
  onClose: () => void;
  accounts: EmailAccount[];
  /** Новое письмо или ответ */
  mode: 'new' | 'reply';
  /** Для reply — исходное письмо */
  replyTo?: EmailMessage | null;
};

function parseEmails(raw: string): string[] {
  return raw
    .split(/[,;\s]+/)
    .map((s) => s.trim())
    .filter(Boolean);
}

function replySubject(original: string | null): string {
  const s = (original || '').trim();
  if (!s) return 'Re: ';
  if (/^re:\s*/i.test(s)) return s;
  return `Re: ${s}`;
}

export const EmailComposeModal: React.FC<EmailComposeModalProps> = ({
  open,
  onClose,
  accounts,
  mode,
  replyTo,
}) => {
  const { t } = useTranslation();
  const [accountId, setAccountId] = useState('');
  const [to, setTo] = useState('');
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    setError(null);
    const first = accounts.find((a) => a.status === 'active') || accounts[0];
    setAccountId(first?.id || '');
    if (mode === 'reply' && replyTo) {
      setTo(replyTo.from);
      setSubject(replySubject(replyTo.subject));
      setBody(
        `\n\n---\n${t('crm.email.inbox.replyTitle')}: ${replyTo.subject || '—'}\n${replyTo.textBody || ''}`.slice(
          0,
          50_000,
        ),
      );
    } else {
      setTo('');
      setSubject('');
      setBody('');
    }
  }, [open, mode, replyTo, accounts, t]);

  const handleSend = async () => {
    setError(null);
    if (!accountId) {
      setError(t('crm.email.inbox.pickAccount'));
      return;
    }
    const recipients = parseEmails(to);
    if (!recipients.length) {
      setError(t('crm.email.inbox.toRequired'));
      return;
    }
    setBusy(true);
    try {
      await sendEmail({
        accountId,
        to: recipients,
        subject: subject.trim() || undefined,
        textBody: body,
        leadId: replyTo?.leadId || undefined,
      });
      onClose();
    } catch (e: any) {
      setError(e?.message || t('crm.email.inbox.sendError'));
    } finally {
      setBusy(false);
    }
  };

  if (!open) return null;

  const title = mode === 'reply' ? t('crm.email.inbox.replyTitle') : t('crm.email.inbox.composeTitle');

  return (
    <div
      className="fixed inset-0 z-[75] flex items-end justify-center bg-slate-900/40 p-3 sm:items-center sm:p-4"
      role="dialog"
      aria-modal
      aria-labelledby="email-compose-title"
    >
      <div className="flex max-h-[92vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-xl">
        <div className="flex shrink-0 items-start justify-between gap-3 border-b border-slate-100 px-4 py-3 sm:px-5 sm:py-4">
          <div className="min-w-0">
            <h2 id="email-compose-title" className="text-base font-semibold text-slate-900">
              {title}
            </h2>
            <p className="mt-1 text-[11px] text-slate-500">{t('crm.email.accounts.subtitle')}</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-slate-200 text-slate-600 hover:bg-slate-50"
          >
            ×
          </button>
        </div>

        <div className="min-h-0 flex-1 space-y-3 overflow-y-auto p-4 text-xs sm:p-5">
          {error ? (
            <div className="rounded-lg border border-rose-200 bg-rose-50 px-3 py-2 text-xs text-rose-900">{error}</div>
          ) : null}

          <div>
            <label className="mb-1 block font-medium text-slate-600">{t('crm.aiAssistant.emailComposer.account')}</label>
            <select
              value={accountId}
              onChange={(e) => setAccountId(e.target.value)}
              className="w-full rounded-xl border border-slate-300 px-3 py-2 text-slate-900"
            >
              <option value="">{t('crm.aiAssistant.emailComposer.pickAccount')}</option>
              {accounts.map((a) => (
                <option key={a.id} value={a.id}>
                  {a.name ? `${a.name} <${a.email}>` : a.email}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="mb-1 block font-medium text-slate-600">{t('crm.email.inbox.to')}</label>
            <input
              type="text"
              value={to}
              onChange={(e) => setTo(e.target.value)}
              className="w-full rounded-xl border border-slate-300 px-3 py-2 text-slate-900"
              placeholder="email@example.com"
            />
          </div>

          <div>
            <label className="mb-1 block font-medium text-slate-600">{t('crm.email.inbox.subject')}</label>
            <input
              type="text"
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              className="w-full rounded-xl border border-slate-300 px-3 py-2 text-slate-900"
            />
          </div>

          <div>
            <label className="mb-1 block font-medium text-slate-600">{t('crm.email.inbox.body')}</label>
            <textarea
              value={body}
              onChange={(e) => setBody(e.target.value)}
              rows={12}
              className="w-full resize-y rounded-xl border border-slate-300 px-3 py-2 font-sans text-slate-900"
            />
          </div>
        </div>

        <div className="flex shrink-0 justify-end gap-2 border-t border-slate-100 px-4 py-3 sm:px-5">
          <button
            type="button"
            onClick={onClose}
            className="rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-semibold text-slate-700 shadow-sm hover:bg-slate-50"
          >
            {t('crm.common.cancel')}
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={() => void handleSend()}
            className="rounded-xl px-4 py-2 text-xs font-semibold text-white shadow-md transition hover:opacity-95 disabled:opacity-50"
            style={{ backgroundColor: TEAL, boxShadow: '0 8px 24px rgba(69,160,148,0.35)' }}
          >
            {busy ? t('crm.email.inbox.sending') : t('crm.email.inbox.send')}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { MainLayout } from '../../layout/MainLayout';
import { CrmShellModal } from '../../components/ui/CrmShellModal';
import { EmailComposeModal } from './EmailComposeModal';
import {
  fetchEmailAccounts,
  fetchEmailMessages,
  fetchEmailMessage,
  patchEmailMessage,
  syncEmailMailboxNow,
  type EmailAccount,
  type EmailMessage,
} from '../../api/email';

const TEAL = '#45a094';

const leadBadgeClass =
  'inline-flex items-center rounded-2xl px-3 py-1 text-xs font-semibold text-white shadow-md transition hover:opacity-95';
const leadBadgeStyle = { backgroundColor: TEAL, boxShadow: '0 6px 20px rgba(69,160,148,0.35)' };

export const EmailInboxPage: React.FC = () => {
  const { t } = useTranslation();
  const [accounts, setAccounts] = useState<EmailAccount[]>([]);
  const [messages, setMessages] = useState<EmailMessage[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string>('');
  const [direction, setDirection] = useState<'incoming' | 'outgoing' | ''>('');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [detail, setDetail] = useState<EmailMessage | null>(null);
  const [syncingId, setSyncingId] = useState<string | null>(null);
  const [composeOpen, setComposeOpen] = useState(false);
  const [composeMode, setComposeMode] = useState<'new' | 'reply'>('new');
  const [syncError, setSyncError] = useState<string | null>(null);

  const loadAccounts = useCallback(async () => {
    try {
      const list = await fetchEmailAccounts();
      setAccounts(list);
    } catch {
      /* ignore */
    }
  }, []);

  const loadMessages = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetchEmailMessages({
        accountId: accountId || undefined,
        direction: direction || undefined,
        limit: 80,
        offset: 0,
      });
      setMessages(res.items);
      setTotal(res.total);
    } catch (e: any) {
      setError(e?.message || 'load failed');
    } finally {
      setLoading(false);
    }
  }, [accountId, direction]);

  useEffect(() => {
    void loadAccounts();
  }, [loadAccounts]);

  useEffect(() => {
    void loadMessages();
  }, [loadMessages]);

  useEffect(() => {
    if (!selectedId) {
      setDetail(null);
      return;
    }
    let alive = true;
    fetchEmailMessage(selectedId)
      .then((m) => {
        if (alive) setDetail(m);
      })
      .catch(() => {
        if (alive) setDetail(null);
      });
    return () => {
      alive = false;
    };
  }, [selectedId]);

  const selectedAccount = useMemo(
    () => accounts.find((a) => a.id === accountId),
    [accounts, accountId],
  );

  const handleSync = async (id: string) => {
    setSyncingId(id);
    setSyncError(null);
    try {
      await syncEmailMailboxNow(id);
      await loadMessages();
      await loadAccounts();
    } catch (e: any) {
      setSyncError(e?.message || 'sync failed');
    } finally {
      setSyncingId(null);
    }
  };

  const handleMarkRead = async () => {
    if (!detail || detail.isRead) return;
    try {
      const m = await patchEmailMessage(detail.id, { isRead: true });
      setDetail(m);
      setMessages((prev) => prev.map((x) => (x.id === m.id ? { ...x, isRead: true } : x)));
    } catch {
      /* ignore */
    }
  };

  const openNewCompose = () => {
    setComposeMode('new');
    setComposeOpen(true);
  };

  const openReply = () => {
    if (!detail || detail.direction !== 'incoming') return;
    setComposeMode('reply');
    setComposeOpen(true);
  };

  return (
    <MainLayout>
      <div className="mx-auto flex w-full max-w-[1600px] min-h-[72vh] flex-col gap-4 px-0 sm:px-1">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <h1 className="text-lg font-semibold text-slate-50">{t('crm.email.inbox.title')}</h1>
            <p className="text-[11px] text-slate-500">{t('crm.email.inbox.subtitle')}</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={openNewCompose}
              disabled={accounts.length === 0}
              className="inline-flex items-center gap-2 rounded-2xl px-3 py-2 text-xs font-semibold text-white shadow-md transition hover:opacity-95 disabled:cursor-not-allowed disabled:opacity-40"
              style={{ backgroundColor: TEAL, boxShadow: '0 8px 24px rgba(69,160,148,0.35)' }}
              title={t('crm.email.inbox.compose')}
            >
              <span className="flex h-6 w-6 items-center justify-center rounded-xl bg-white/20 text-lg font-light leading-none">
                +
              </span>
              {t('crm.email.inbox.compose')}
            </button>
            <Link
              to="/email"
              className="rounded-xl border border-slate-700 px-3 py-1.5 text-xs text-slate-200 hover:bg-slate-800"
            >
              {t('crm.email.accounts.title')}
            </Link>
            <button
              type="button"
              onClick={() => void loadMessages()}
              className="rounded-xl bg-lumiva-accent px-3 py-1.5 text-xs font-semibold text-slate-950 hover:opacity-90"
            >
              {t('crm.email.inbox.refresh')}
            </button>
          </div>
        </div>

        <div className="flex flex-wrap gap-2 text-xs">
          <select
            value={accountId}
            onChange={(e) => setAccountId(e.target.value)}
            className="rounded-xl border border-slate-700 bg-slate-900 px-2 py-1.5 text-slate-200"
          >
            <option value="">{t('crm.email.inbox.allMailboxes')}</option>
            {accounts.map((a) => (
              <option key={a.id} value={a.id}>
                {a.email}
                {a.hasOAuthTokens ? ' · OAuth' : ''}
              </option>
            ))}
          </select>
          <select
            value={direction}
            onChange={(e) => setDirection(e.target.value as typeof direction)}
            className="rounded-xl border border-slate-700 bg-slate-900 px-2 py-1.5 text-slate-200"
          >
            <option value="">{t('crm.email.inbox.filterAll')}</option>
            <option value="incoming">{t('crm.email.inbox.filterIncoming')}</option>
            <option value="outgoing">{t('crm.email.inbox.filterOutgoing')}</option>
          </select>
          {accountId && selectedAccount?.hasOAuthTokens ? (
            <button
              type="button"
              disabled={syncingId === accountId}
              onClick={() => void handleSync(accountId)}
              className="rounded-xl border border-sky-700/80 bg-sky-950/40 px-3 py-1.5 text-sky-200 hover:bg-sky-950/70 disabled:opacity-50"
            >
              {syncingId === accountId ? t('crm.email.inbox.syncInProgress') : t('crm.email.accounts.syncNow')}
            </button>
          ) : null}
        </div>

        {error ? (
          <div className="rounded-xl border border-red-800/50 bg-red-950/30 px-3 py-2 text-xs text-red-300">{error}</div>
        ) : null}

        <div className="grid min-h-0 flex-1 gap-4 xl:grid-cols-[minmax(260px,340px)_minmax(0,1fr)]">
          <div className="flex min-h-[min(85vh,880px)] max-h-[min(85vh,880px)] flex-col overflow-hidden rounded-2xl border border-slate-800 bg-slate-900/60">
            <div className="border-b border-slate-800 px-3 py-2 text-[10px] font-medium uppercase tracking-wide text-slate-500">
              {total} · {loading ? t('crm.email.inbox.load') : ''}
            </div>
            <div className="min-h-0 flex-1 overflow-y-auto">
              {!loading && messages.length === 0 ? (
                <div className="p-4 text-xs text-slate-500">{t('crm.email.inbox.empty')}</div>
              ) : null}
              {messages.map((m) => (
                <button
                  key={m.id}
                  type="button"
                  onClick={() => setSelectedId(m.id)}
                  className={
                    'w-full border-b border-slate-800/80 px-3 py-2.5 text-left transition-colors hover:bg-slate-800/50 ' +
                    (selectedId === m.id ? 'bg-slate-800/70' : '') +
                    (!m.isRead ? ' border-l-2 border-l-[#45a094]' : '')
                  }
                >
                  <div className="truncate text-xs font-semibold text-slate-100">
                    {m.subject || '—'}
                  </div>
                  <div className="mt-0.5 truncate text-[10px] text-slate-400">
                    {m.direction === 'incoming' ? m.from : m.to?.join(', ')}
                  </div>
                  <div className="mt-1 text-[10px] text-slate-500">
                    {new Date(m.date).toLocaleString()}
                  </div>
                </button>
              ))}
            </div>
          </div>

          <div className="flex min-h-[min(85vh,880px)] max-h-[min(85vh,880px)] flex-col overflow-hidden rounded-2xl border border-slate-800 bg-slate-900/40">
            {!detail ? (
              <div className="flex flex-1 items-center justify-center p-6 text-sm text-slate-500">
                {t('crm.email.inbox.selectMessage')}
              </div>
            ) : (
              <div className="flex min-h-0 flex-1 flex-col">
                <div className="shrink-0 border-b border-slate-800 px-4 py-3 sm:px-5">
                  <h2 className="text-sm font-semibold text-slate-50">{detail.subject || '—'}</h2>
                  <div className="mt-2 space-y-1 text-[11px] text-slate-400">
                    <div>
                      <span className="text-slate-500">From:</span> {detail.fromName ? `${detail.fromName} ` : ''}
                      &lt;{detail.from}&gt;
                    </div>
                    <div>
                      <span className="text-slate-500">To:</span> {detail.to?.join(', ')}
                    </div>
                    <div className="flex flex-wrap items-center gap-2 pt-2">
                      {detail.direction === 'incoming' ? (
                        <button
                          type="button"
                          onClick={openReply}
                          disabled={accounts.length === 0}
                          className="rounded-xl border border-slate-600 px-3 py-1 text-[11px] font-medium text-slate-100 hover:bg-slate-800 disabled:opacity-40"
                        >
                          {t('crm.email.inbox.reply')}
                        </button>
                      ) : null}
                      {detail.leadId ? (
                        <Link to={`/leads/${detail.leadId}`} className={leadBadgeClass} style={leadBadgeStyle}>
                          {t('crm.email.inbox.openLead')}
                        </Link>
                      ) : null}
                      {detail.meta?.hasCalendarAttachment ? (
                        <span className="rounded-lg bg-amber-900/40 px-2 py-0.5 text-amber-200">
                          {t('crm.email.inbox.calendarInvite')}
                        </span>
