export class CreateEmailFolderDto {
  @IsUUID()
  accountId: string;

  @IsString()
  @MinLength(1)
  @MaxLength(255)
  name: string;

  @IsOptional()
  @IsUUID()
  parentId?: string | null;
}

import { IsArray, IsInt, IsOptional, IsUUID, ValidateNested } from 'class-validator';
import { Type } from 'class-transformer';

export class ReorderEmailFolderItemDto {
  @IsUUID()
  id: string;

  @IsInt()
  sortOrder: number;

  @IsOptional()
  @IsUUID()
  parentId?: string | null;
}

export class ReorderEmailFoldersDto {
  @IsUUID()
  accountId: string;

  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => ReorderEmailFolderItemDto)
  items: ReorderEmailFolderItemDto[];
}

import { IsInt, IsOptional, IsString, IsUUID, MaxLength, MinLength } from 'class-validator';

export class PatchEmailFolderDto {
  @IsOptional()
  @IsString()
  @MinLength(1)
