  name?: string;

  @IsOptional()
  @IsUUID()
  parentId?: string | null;

  @IsOptional()
  @IsInt()
  sortOrder?: number;
}

import { IsOptional, IsString } from 'class-validator';

export class PatchEmailSignatureDto {
  @IsOptional()
  @IsString()
  signatureHtml?: string | null;

  @IsOptional()
  @IsString()
  signatureText?: string | null;
}

