const TEAL = '#45a094';

function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => {
      const s = r.result as string;
      const i = s.indexOf(',');
      resolve(i >= 0 ? s.slice(i + 1) : s);
    };
    r.onerror = reject;
    r.readAsDataURL(file);
  });
}

export type EmailComposePanelProps = {
  open: boolean;
  mode: 'new' | 'reply';
  accounts: EmailAccount[];
  accountId: string;
  onAccountChange: (id: string) => void;
  initialTo: string;
  initialSubject: string;
  initialHtml: string;
  resetKey: string | number;
  leadId?: string | null;
  onClose: () => void;
  onSent: () => void;
};

export const EmailComposePanel: React.FC<EmailComposePanelProps> = ({
  open,
  mode,
  accounts,
  accountId,
  onAccountChange,
  initialTo,
  initialSubject,
  initialHtml,
  resetKey,
  leadId,
  onClose,
  onSent,
}) => {
  const { t } = useTranslation();
  const [to, setTo] = useState('');
  const [subject, setSubject] = useState('');
  const [htmlBody, setHtmlBody] = useState('<p></p>');
  const [plainBody, setPlainBody] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  React.useEffect(() => {
    if (!open) return;
    setTo(initialTo);
    setSubject(initialSubject);
    setHtmlBody(initialHtml || '<p></p>');
    setPlainBody('');
    setFiles([]);
    setErr(null);
  }, [open, initialTo, initialSubject, initialHtml, resetKey]);

  const onEditorChange = useCallback((html: string, plain: string) => {
    setHtmlBody(html);
    setPlainBody(plain);
  }, []);

  const parseTo = (raw: string) =>
    raw
      .split(/[,;\s]+/)
      .map((s) => s.trim())
      .filter(Boolean);

  const handleSend = async () => {
    setErr(null);
    if (!accountId) {
      setErr(t('crm.email.inbox.pickAccount'));
      return;
    }
    const recipients = parseTo(to);
    if (!recipients.length) {
      setErr(t('crm.email.inbox.toRequired'));
      return;
    }
    setBusy(true);
    try {
      const attachments =
        files.length > 0
          ? await Promise.all(
              files.map(async (f) => ({
                filename: f.name,
                contentType: f.type || 'application/octet-stream',
                contentBase64: await fileToBase64(f),
              })),
            )
          : undefined;
      await sendEmail({
        accountId,
        to: recipients,
        subject: subject.trim() || undefined,
        htmlBody: htmlBody.replace(/<p><\/p>/g, '').trim() ? htmlBody : undefined,
        textBody: plainBody.trim() || undefined,
        leadId: leadId || undefined,
        attachments,
      });
      onSent();
      onClose();
    } catch (e: any) {
      setErr(e?.message || t('crm.email.inbox.sendError'));
    } finally {
      setBusy(false);
    }
  };

  if (!open) return null;

  return (
    <div className="flex max-h-[min(48vh,520px)] min-h-[200px] shrink-0 flex-col border-t border-slate-700/90 bg-slate-950/95">
      <div className="flex shrink-0 items-center justify-between gap-2 border-b border-slate-800 px-3 py-2">
        <span className="text-xs font-semibold text-slate-200">
          {mode === 'reply' ? t('crm.email.inbox.replyTitle') : t('crm.email.inbox.composeTitle')}
        </span>
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg border border-slate-600 px-2.5 py-1 text-[11px] text-slate-300 hover:bg-slate-800"
          >
            {t('crm.common.cancel')}
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={() => void handleSend()}
            className="rounded-lg px-3 py-1 text-[11px] font-semibold text-white disabled:opacity-50"
            style={{ backgroundColor: TEAL }}
          >
            {busy ? t('crm.email.inbox.sending') : t('crm.email.inbox.send')}
          </button>
        </div>
      </div>

      <div className="min-h-0 flex-1 space-y-2 overflow-y-auto px-3 py-2">
        {err ? <div className="rounded-lg border border-rose-800/50 bg-rose-950/40 px-2 py-1 text-[11px] text-rose-200">{err}</div> : null}

        <div className="grid gap-2 sm:grid-cols-2">
          <div>
            <label className="mb-0.5 block text-[10px] uppercase tracking-wide text-slate-500">
              {t('crm.aiAssistant.emailComposer.account')}
            </label>
            <select
              value={accountId}
              onChange={(e) => onAccountChange(e.target.value)}
              className="w-full rounded-lg border border-slate-600 bg-slate-900 px-2 py-1.5 text-xs text-slate-100"
            >
              <option value="">{t('crm.aiAssistant.emailComposer.pickAccount')}</option>
              {accounts.map((a) => (
                <option key={a.id} value={a.id}>
                  {a.name ? `${a.name} · ${a.email}` : a.email}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="mb-0.5 block text-[10px] uppercase tracking-wide text-slate-500">
              {t('crm.email.inbox.to')}
            </label>
            <input
              type="text"
              value={to}
              onChange={(e) => setTo(e.target.value)}
              className="w-full rounded-lg border border-slate-600 bg-slate-900 px-2 py-1.5 text-xs text-slate-100"
              placeholder="email@…"
            />
          </div>
        </div>

        <div>
          <label className="mb-0.5 block text-[10px] uppercase tracking-wide text-slate-500">
            {t('crm.email.inbox.subject')}
          </label>
          <input
            type="text"
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            className="w-full rounded-lg border border-slate-600 bg-slate-900 px-2 py-1.5 text-xs text-slate-100"
          />
        </div>

        <div>
          <label className="mb-0.5 block text-[10px] uppercase tracking-wide text-slate-500">
            {t('crm.email.inbox.body')}
          </label>
          <EmailRichEditor
            key={resetKey}
            content={htmlBody}
            onChange={onEditorChange}
            placeholder={t('crm.email.inbox.body')}
            resetKey={resetKey}
          />
        </div>

        <div>
          <label className="mb-0.5 block text-[10px] uppercase tracking-wide text-slate-500">
            {t('crm.email.inbox.attachments')}
          </label>
          <input
            type="file"
            multiple
            className="block w-full text-[11px] text-slate-400 file:mr-2 file:rounded-lg file:border-0 file:bg-slate-700 file:px-2 file:py-1 file:text-slate-200"
