          {files.length > 0 ? (
            <ul className="mt-1 space-y-0.5 text-[10px] text-slate-500">
              {files.map((f) => (
                <li key={f.name + f.size}>{f.name}</li>
              ))}
            </ul>
          ) : null}
        </div>
      </div>
    </div>
  );
};

