  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [accountId, setAccountId] = useState<string>('');
  const [selectedFolderId, setSelectedFolderId] = useState<string>('');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [detail, setDetail] = useState<EmailMessage | null>(null);
  const [syncingId, setSyncingId] = useState<string | null>(null);
  const [syncError, setSyncError] = useState<string | null>(null);

  const [composeOpen, setComposeOpen] = useState(false);
  const [composeMode, setComposeMode] = useState<'new' | 'reply'>('new');
  const [composeResetKey, setComposeResetKey] = useState(0);
  const [composeTo, setComposeTo] = useState('');
  const [composeSubject, setComposeSubject] = useState('');
  const [composeHtml, setComposeHtml] = useState('<p></p>');
  const [composeLeadId, setComposeLeadId] = useState<string | null>(null);

  const loadAccounts = useCallback(async () => {
    try {
      const list = await fetchEmailAccounts();
      setAccounts(list);
    } catch {
      /* ignore */
    }
  }, []);

  const loadFolders = useCallback(async () => {
    if (!accountId) {
      setFolders([]);
      return;
    }
    setFolderLoading(true);
    try {
      const list = await fetchEmailFolders(accountId);
      setFolders(list);
    } catch {
      setFolders([]);
    } finally {
      setFolderLoading(false);
    }
  }, [accountId]);

  const loadMessages = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const query: {
        accountId?: string;
        folderId?: string;
        limit: number;
        offset: number;
      } = { limit: 100, offset: 0 };
      if (accountId) query.accountId = accountId;
      if (accountId && selectedFolderId) query.folderId = selectedFolderId;
      const res = await fetchEmailMessages(query);
      setMessages(res.items);
      setTotal(res.total);
    } catch (e: any) {
      setError(e?.message || 'load failed');
    } finally {
      setLoading(false);
    }
  }, [accountId, selectedFolderId]);

  useEffect(() => {
    void loadAccounts();
  }, [loadAccounts]);

  useEffect(() => {
    void loadFolders();
  }, [loadFolders]);

  useEffect(() => {
    if (!folders.length) {
      setSelectedFolderId('');
      return;
    }
    setSelectedFolderId((prev) => {
      if (prev && folders.some((f) => f.id === prev)) return prev;
      return folders.find((f) => f.systemKey === 'inbox')?.id || folders[0].id;
    });
  }, [folders]);

  useEffect(() => {
    void loadMessages();
  }, [loadMessages]);

  useEffect(() => {
    if (!selectedId) {
      setDetail(null);
      return;
    }
    let alive = true;
    fetchEmailMessage(selectedId)
      .then((m) => {
        if (alive) setDetail(m);
      })
      .catch(() => {
        if (alive) setDetail(null);
      });
    return () => {
      alive = false;
    };
  }, [selectedId]);

  const selectedAccount = useMemo(
    () => accounts.find((a) => a.id === accountId),
    [accounts, accountId],
  );

  const trashFolderId = useMemo(
    () => folders.find((f) => f.systemKey === 'trash')?.id,
    [folders],
  );

  const folderTree = useMemo(() => orderedFolderTree(folders), [folders]);

  const folderLabel = useCallback(
    (f: EmailFolder) => {
      if (f.systemKey === 'inbox') return t('crm.email.inbox.sysFolder.inbox');
      if (f.systemKey === 'sent') return t('crm.email.inbox.sysFolder.sent');
      if (f.systemKey === 'trash') return t('crm.email.inbox.sysFolder.trash');
      return f.name;
    },
    [t],
  );

  const handleSync = async (id: string) => {
    setSyncingId(id);
    setSyncError(null);
    try {
      await syncEmailMailboxNow(id);
      await loadMessages();
      await loadFolders();
      await loadAccounts();
    } catch (e: any) {
      setSyncError(e?.message || 'sync failed');
    } finally {
      setSyncingId(null);
    }
  };

  const handleMarkRead = async () => {
    if (!detail || detail.isRead) return;
    try {
      const m = await patchEmailMessage(detail.id, { isRead: true });
      setDetail(m);
      setMessages((prev) => prev.map((x) => (x.id === m.id ? { ...x, isRead: true } : x)));
    } catch {
      /* ignore */
    }
  };

  const moveMessageToFolder = async (messageId: string, folderId: string) => {
    try {
      await patchEmailMessage(messageId, { crmFolderId: folderId });
      await loadMessages();
      if (selectedId === messageId) {
        const m = await fetchEmailMessage(messageId);
        setDetail(m);
      }
    } catch {
      /* ignore */
    }
  };

  const openNewCompose = () => {
    setComposeMode('new');
    setComposeTo('');
    setComposeSubject('');
    setComposeHtml('<p></p>');
    setComposeLeadId(null);
    setComposeResetKey((k) => k + 1);
    setComposeOpen(true);
  };

  const openReply = () => {
    if (!detail || detail.direction !== 'incoming') return;
    setComposeMode('reply');
    setComposeTo(detail.from);
    setComposeSubject(replySubject(detail.subject));
    setComposeHtml(replyInitialHtml(detail));
    setComposeLeadId(detail.leadId);
    setComposeResetKey((k) => k + 1);
    setComposeOpen(true);
  };

  const createFolder = async (parentId: string | null) => {
    if (!accountId) return;
    const name = window.prompt(t('crm.email.inbox.newFolder'), '');
    if (!name?.trim()) return;
    try {
      await createEmailFolder({ accountId, name: name.trim(), parentId });
      await loadFolders();
    } catch {
      /* ignore */
    }
  };

  const renameFolder = async (f: EmailFolder) => {
    if (f.systemKey) return;
    const name = window.prompt(t('crm.email.inbox.renameFolder'), f.name);
    if (!name?.trim()) return;
    try {
      await patchEmailFolder(f.id, { name: name.trim() });
      await loadFolders();
    } catch {
      /* ignore */
    }
  };

  const removeFolder = async (f: EmailFolder) => {
    if (f.systemKey) return;
    if (!window.confirm(t('crm.email.inbox.deleteFolderConfirm'))) return;
    try {
      await deleteEmailFolder(f.id);
      await loadFolders();
      await loadMessages();
    } catch {
      /* ignore */
    }
  };

  const reorderSibling = async (folderId: string, delta: number) => {
    if (!accountId) return;
    const f = folders.find((x) => x.id === folderId);
    if (!f) return;
    const pid = f.parentId ?? null;
    const sibs = folders
      .filter((x) => (x.parentId ?? null) === pid)
      .sort((a, b) => a.sortOrder - b.sortOrder || a.createdAt.localeCompare(b.createdAt));
    const idx = sibs.findIndex((x) => x.id === folderId);
    const j = idx + delta;
    if (idx < 0 || j < 0 || j >= sibs.length) return;
    const next = [...sibs];
    [next[idx], next[j]] = [next[j], next[idx]];
    const items = next.map((x, i) => ({
      id: x.id,
      sortOrder: i,
      parentId: x.parentId ?? null,
    }));
    try {
      await reorderEmailFolders({ accountId, items });
      await loadFolders();
    } catch {
      /* ignore */
    }
  };

  const onFolderDrop = async (e: React.DragEvent, targetFolderId: string | 'root') => {
    e.preventDefault();
    e.stopPropagation();
    const mid = e.dataTransfer.getData('messageId');
    const fid = e.dataTransfer.getData('folderId');
    if (mid && accountId) {
      const dest =
        targetFolderId === 'root'
          ? folders.find((x) => x.systemKey === 'inbox')?.id
          : targetFolderId;
      if (dest) await moveMessageToFolder(mid, dest);
      return;
    }
    if (fid && accountId) {
      const dragged = folders.find((x) => x.id === fid);
      if (!dragged || dragged.systemKey) return;
      const parentId = targetFolderId === 'root' ? null : targetFolderId;
      if (parentId === fid) return;
      try {
        await patchEmailFolder(fid, { parentId });
        await loadFolders();
      } catch {
        /* ignore */
      }
    }
  };

  return (
    <MainLayout>
      <div className="mx-auto flex w-full max-w-[1680px] min-h-[72vh] flex-col gap-3 px-0 sm:px-1">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <h1 className="text-lg font-semibold text-slate-50">{t('crm.email.inbox.title')}</h1>
            <p className="text-[11px] text-slate-500">{t('crm.email.inbox.subtitle')}</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={openNewCompose}
              disabled={accounts.length === 0}
              className="inline-flex items-center gap-1.5 rounded-xl px-3 py-1.5 text-xs font-semibold text-white transition hover:opacity-95 disabled:cursor-not-allowed disabled:opacity-40"
              style={{ backgroundColor: TEAL }}
              title={t('crm.email.inbox.compose')}
            >
              <span className="text-sm leading-none">+</span>
              {t('crm.email.inbox.compose')}
            </button>
            <Link
              to="/email"
              className="rounded-xl border border-slate-700 px-3 py-1.5 text-xs text-slate-200 hover:bg-slate-800"
            >
              {t('crm.email.accounts.title')}
            </Link>
            <button
              type="button"
              onClick={() => void loadMessages()}
              className="rounded-xl bg-lumiva-accent px-3 py-1.5 text-xs font-semibold text-slate-950 hover:opacity-90"
            >
              {t('crm.email.inbox.refresh')}
            </button>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-2 text-xs">
          <select
            value={accountId}
            onChange={(e) => {
              setAccountId(e.target.value);
              setSelectedId(null);
            }}
            className="rounded-xl border border-slate-700 bg-slate-900 px-2 py-1.5 text-slate-200"
          >
            <option value="">{t('crm.email.inbox.allMailboxes')}</option>
            {accounts.map((a) => (
              <option key={a.id} value={a.id}>
                {a.email}
                {a.hasOAuthTokens ? ' · OAuth' : ''}
              </option>
            ))}
          </select>
          {accountId && selectedAccount?.hasOAuthTokens ? (
            <button
              type="button"
              disabled={syncingId === accountId}
              onClick={() => void handleSync(accountId)}
              className="rounded-xl border border-sky-700/80 bg-sky-950/40 px-3 py-1.5 text-sky-200 hover:bg-sky-950/70 disabled:opacity-50"
            >
              {syncingId === accountId ? t('crm.email.inbox.syncInProgress') : t('crm.email.accounts.syncNow')}
            </button>
          ) : null}
        </div>

        {error ? (
          <div className="rounded-xl border border-red-800/50 bg-red-950/30 px-3 py-2 text-xs text-red-300">{error}</div>
        ) : null}

        <div
          className={`flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl border border-slate-800 bg-slate-900/50 ${
            composeOpen ? 'min-h-[min(88vh,920px)]' : 'min-h-[min(78vh,880px)]'
          }`}
        >
          <div className="grid min-h-0 flex-1 grid-cols-1 divide-y divide-slate-800/80 lg:grid-cols-[minmax(0,200px)_minmax(260px,34%)_minmax(0,1fr)] lg:divide-x lg:divide-y-0">
            <aside className="flex max-h-[220px] min-h-0 flex-col lg:max-h-none">
              <div className="shrink-0 border-b border-slate-800/80 px-2 py-2">
                <div className="text-[10px] font-medium uppercase tracking-wide text-slate-500">{t('crm.email.inbox.folders')}</div>
                {!accountId ? (
                  <p className="mt-1 text-[10px] text-slate-500">{t('crm.email.inbox.selectMailboxForFolders')}</p>
                ) : (
                  <div className="mt-1 flex flex-wrap gap-1">
                    <button
                      type="button"
                      onClick={() => void createFolder(null)}
                      className="rounded-lg border border-slate-600 px-2 py-0.5 text-[10px] text-slate-300 hover:bg-slate-800"
                    >
                      + {t('crm.email.inbox.newFolder')}
                    </button>
                    <div
                      className="rounded-lg border border-dashed border-slate-600 px-2 py-0.5 text-[10px] text-slate-500"
                      onDragOver={(e) => e.preventDefault()}
                      onDrop={(e) => void onFolderDrop(e, 'root')}
                    >
                      {t('crm.email.inbox.dropFolderRoot')}
                    </div>
                  </div>
                )}
              </div>
              <div className="min-h-0 flex-1 overflow-y-auto px-1 py-1">
                {accountId && folderLoading ? (
                  <div className="p-2 text-[10px] text-slate-500">{t('crm.email.inbox.load')}</div>
                ) : null}
                {accountId && !folderLoading && folderTree.map(({ f, depth }) => (
                  <div
                    key={f.id}
                    draggable={!f.systemKey}
                    onDragStart={(e) => {
                      e.dataTransfer.setData('folderId', f.id);
                      e.dataTransfer.effectAllowed = 'move';
                    }}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={(e) => void onFolderDrop(e, f.id)}
                    className={`group mb-0.5 rounded-lg border border-transparent px-1 py-1 text-left text-[11px] transition hover:border-slate-700/80 hover:bg-slate-800/40 ${
                      selectedFolderId === f.id ? 'border-slate-600 bg-slate-800/60' : ''
                    }`}
                    style={{ paddingLeft: 6 + depth * 10 }}
                  >
                    <button
                      type="button"
                      onClick={() => setSelectedFolderId(f.id)}
                      className="w-full truncate text-left font-medium text-slate-200"
                    >
                      {folderLabel(f)}
                    </button>
                    {!f.systemKey ? (
                      <div className="mt-0.5 flex flex-wrap gap-0.5 opacity-90">
                        <button
                          type="button"
                          className="rounded px-1 text-[9px] text-slate-500 hover:bg-slate-700 hover:text-slate-300"
                          onClick={() => void reorderSibling(f.id, -1)}
                        >
                          {t('crm.email.inbox.folderUp')}
                        </button>
                        <button
                          type="button"
                          className="rounded px-1 text-[9px] text-slate-500 hover:bg-slate-700 hover:text-slate-300"
                          onClick={() => void reorderSibling(f.id, 1)}
                        >
                          {t('crm.email.inbox.folderDown')}
                        </button>
                        <button
                          type="button"
                          className="rounded px-1 text-[9px] text-slate-500 hover:bg-slate-700 hover:text-slate-300"
                          onClick={() => void createFolder(f.id)}
                        >
                          {t('crm.email.inbox.newSubfolder')}
                        </button>
                        <button
                          type="button"
                          className="rounded px-1 text-[9px] text-slate-500 hover:bg-slate-700 hover:text-slate-300"
                          onClick={() => void renameFolder(f)}
                        >
                          {t('crm.email.inbox.renameFolder')}
                        </button>
                        <button
                          type="button"
                          className="rounded px-1 text-[9px] text-rose-400/90 hover:bg-rose-950/40"
                          onClick={() => void removeFolder(f)}
                        >
                          {t('crm.email.inbox.deleteFolder')}
                        </button>
                      </div>
                    ) : null}
                  </div>
                ))}
              </div>
              {accountId ? (
                <p className="shrink-0 border-t border-slate-800/80 px-2 py-1 text-[9px] text-slate-600">{t('crm.email.inbox.dropOnFolder')}</p>
              ) : null}
            </aside>

            <div className="flex min-h-[200px] min-h-0 flex-col border-slate-800/80 lg:border-r">
              <div className="shrink-0 border-b border-slate-800 px-2 py-2 text-[10px] font-medium uppercase tracking-wide text-slate-500">
                {total} · {loading ? t('crm.email.inbox.load') : ''}
              </div>
              <div className="min-h-0 flex-1 overflow-y-auto">
                {!loading && messages.length === 0 ? (
                  <div className="p-3 text-xs text-slate-500">{t('crm.email.inbox.empty')}</div>
                ) : null}
                {messages.map((m) => (
                  <button
                    key={m.id}
                    type="button"
                    draggable
                    onDragStart={(e) => {
                      e.dataTransfer.setData('messageId', m.id);
                      e.dataTransfer.effectAllowed = 'move';
                    }}
                    onClick={() => setSelectedId(m.id)}
                    className={
                      'w-full border-b border-slate-800/80 px-3 py-2 text-left transition-colors hover:bg-slate-800/50 ' +
                      (selectedId === m.id ? 'bg-slate-800/70' : '') +
                      (!m.isRead ? ' border-l-2 border-l-[#45a094]' : '')
                    }
                  >
                    <div className="truncate text-xs font-semibold text-slate-100">{m.subject || '—'}</div>
                    <div className="mt-0.5 truncate text-[10px] text-slate-400">
                      {m.direction === 'incoming' ? m.from : m.to?.join(', ')}
                    </div>
                    <div className="mt-1 text-[10px] text-slate-500">{new Date(m.date).toLocaleString()}</div>
                  </button>
                ))}
              </div>
            </div>

            <div className="flex min-h-[240px] min-h-0 flex-col">
              {!detail ? (
                <div className="flex flex-1 items-center justify-center p-6 text-sm text-slate-500">
                  {t('crm.email.inbox.selectMessage')}
                </div>
              ) : (
                <div className="flex min-h-0 flex-1 flex-col">
                  <div className="shrink-0 border-b border-slate-800 px-3 py-3 sm:px-4">
                    <h2 className="text-sm font-semibold text-slate-50">{detail.subject || '—'}</h2>
                    <div className="mt-2 space-y-1 text-[11px] text-slate-400">
                      <div>
                        <span className="text-slate-500">From:</span> {detail.fromName ? `${detail.fromName} ` : ''}
                        &lt;{detail.from}&gt;
                      </div>
                      <div>
                        <span className="text-slate-500">To:</span> {detail.to?.join(', ')}
                      </div>
                      <div className="flex flex-wrap items-center gap-2 pt-2">
                        {detail.direction === 'incoming' ? (
                          <button
                            type="button"
                            onClick={openReply}
                            disabled={accounts.length === 0}
                            className="rounded-xl border border-slate-600 px-3 py-1 text-[11px] font-medium text-slate-100 hover:bg-slate-800 disabled:opacity-40"
                          >
                            {t('crm.email.inbox.reply')}
                          </button>
                        ) : null}
                        {trashFolderId ? (
                          <button
                            type="button"
                            onClick={() => void moveMessageToFolder(detail.id, trashFolderId)}
                            className="rounded-xl border border-rose-900/50 bg-rose-950/30 px-3 py-1 text-[11px] text-rose-200 hover:bg-rose-950/50"
                          >
                            {t('crm.email.inbox.moveToTrash')}
                          </button>
                        ) : null}
                        {detail.leadId ? (
                          <Link to={`/leads/${detail.leadId}`} className={leadBadgeClass} style={leadBadgeStyle}>
                            {t('crm.email.inbox.openLead')}
                          </Link>
                        ) : null}
                        {detail.meta?.hasCalendarAttachment ? (
                          <span className="rounded-lg bg-amber-900/40 px-2 py-0.5 text-amber-200">
                            {t('crm.email.inbox.calendarInvite')}
                          </span>
                        ) : null}
                        {!detail.isRead ? (
                          <button
                            type="button"
                            onClick={() => void handleMarkRead()}
                            className="rounded-lg border border-slate-600 px-2 py-0.5 text-slate-200 hover:bg-slate-800"
                          >
                            {t('crm.email.inbox.markRead')}
                          </button>
                        ) : null}
                      </div>
                    </div>
                  </div>
                  <div className="min-h-0 flex-1 overflow-y-auto px-3 py-3 text-sm text-slate-200 sm:px-5 sm:py-4">
                    {detail.htmlBody ? (
                      <div
                        className="email-html-body prose prose-invert max-w-none text-sm [&_*]:max-w-full [&_img]:h-auto [&_img]:max-w-full [&_table]:max-w-full"
                        dangerouslySetInnerHTML={{ __html: detail.htmlBody }}
                      />
                    ) : (
                      <pre className="w-full max-w-none whitespace-pre-wrap break-words font-sans text-sm">
                        {detail.textBody || '—'}
                      </pre>
                    )}
                  </div>
                </div>
              )}
            </div>
          </div>

          <EmailComposePanel
            open={composeOpen}
            mode={composeMode}
            accounts={accounts}
            accountId={accountId || accounts[0]?.id || ''}
            onAccountChange={(id) => {
              setAccountId(id);
              setSelectedId(null);
            }}
            initialTo={composeTo}
            initialSubject={composeSubject}
            initialHtml={composeHtml}
            resetKey={composeResetKey}
            leadId={composeLeadId}
            onClose={() => setComposeOpen(false)}
            onSent={() => void loadMessages()}
          />
        </div>
      </div>

      <button
        type="button"
        onClick={openNewCompose}
        disabled={accounts.length === 0}
        className="fixed bottom-5 right-5 z-40 flex h-12 w-12 items-center justify-center rounded-xl text-xl font-light text-white shadow-lg transition hover:opacity-95 disabled:hidden md:hidden"
        style={{ backgroundColor: TEAL }}
        aria-label={t('crm.email.inbox.compose')}
      >
        +
      </button>

      <CrmShellModal
        open={!!syncError}
        title={t('crm.common.modalError')}
        message={syncError || ''}
        variant="error"
        onClose={() => setSyncError(null)}
      />
    </MainLayout>
  );
};

