                  >
                    {t('crm.email.inbox.folderDown')}
                  </button>
                  <button
                    type="button"
                    className="rounded px-1 text-[9px] text-slate-500 hover:bg-slate-700 hover:text-slate-300"
                    onClick={() => void createFolder(f.id)}
                  >
                    {t('crm.email.inbox.newSubfolder')}
                  </button>
                  <button
                    type="button"
                    className="rounded px-1 text-[9px] text-slate-500 hover:bg-slate-700 hover:text-slate-300"
                    onClick={() => void renameFolder(f)}
                  >
                    {t('crm.email.inbox.renameFolder')}
                  </button>
                  <button
                    type="button"
                    className="rounded px-1 text-[9px] text-rose-400/90 hover:bg-rose-950/40"
                    onClick={() => void removeFolder(f)}
                  >
                    {t('crm.email.inbox.deleteFolder')}
                  </button>
                </div>
              ) : null}
            </div>
          ))}
      </div>
      {accountId ? (
        <p className="shrink-0 border-t border-slate-800/80 px-2 py-1 text-[9px] text-slate-600">{t('crm.email.inbox.dropOnFolder')}</p>
      ) : null}
    </aside>
  );

  return (
    <MainLayout>
      <div className="mx-auto flex w-full max-w-[1680px] min-h-[72vh] flex-col gap-3 px-0 sm:px-1">
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <h1 className="text-lg font-semibold text-slate-50">{t('crm.email.inbox.title')}</h1>
            <p className="text-[11px] text-slate-500">{t('crm.email.inbox.subtitle')}</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <button
              type="button"
              onClick={openNewCompose}
