function systemFolderEmoji(key: string | null): string {
  if (key === 'inbox') return '📥';
  if (key === 'sent') return '📤';
  if (key === 'trash') return '🗑️';
  return '📁';
}

function messageRowIcon(m: EmailMessage): string {
  if (m.meta && typeof m.meta === 'object' && (m.meta as { hasCalendarAttachment?: boolean }).hasCalendarAttachment) {
    return '📅';
  }
  const subj = (m.subject || '').toLowerCase();
  if (/оплат|платеж|payment|invoice|счёт|счет|eur|€|\beuro\b|usd|\$|цена|price/.test(subj)) return '€';
  if (/заметк|note|напоминан|reminder|todo|задач|draft|черновик/.test(subj)) return '✏️';
  return '✉️';
}

